import{_ as e,o as s,c as n,am as p}from"./chunks/framework.CiF4W93w.js";const m=JSON.parse('{"title":"MySQL调优操作","description":"","frontmatter":{"title":"MySQL调优操作","excerpt":"哔哩哔哩上面的一门调优课程，进行学习并记录相关的笔记","date":"2025-06-20 07:35:20","updated":"2025-06-20 07:35:20"},"headers":[],"relativePath":"数据库/DB_MySQL/MySQL调优操作/index.md","filePath":"数据库/DB_MySQL/MySQL调优操作/index.md","lastUpdated":null}'),i={name:"数据库/DB_MySQL/MySQL调优操作/index.md"};function l(t,a,o,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[p(`<p>链接地址： <a href="https://www.bilibili.com/video/BV1SD42157HR" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1SD42157HR</a></p><p>在演示之前，添加部分的数据</p><p>新建表</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATE TABLE employees (</span></span>
<span class="line"><span>    id INT AUTO_INCREMENT PRIMARY KEY,</span></span>
<span class="line"><span>    name VARCHAR(100),</span></span>
<span class="line"><span>	age INT,</span></span>
<span class="line"><span>    department_id INT,</span></span>
<span class="line"><span>    hire_date DATE</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>索引基础操作</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#添加索引</span></span>
<span class="line"><span>CREATE INDEX idx_department_id ON employees(department_id);</span></span>
<span class="line"><span># 删除索引</span></span>
<span class="line"><span>DROP INDEX idx_department_id ON employees;</span></span>
<span class="line"><span># 新增索引</span></span>
<span class="line"><span>ALTER TABLE employees ADD INDEX idx_department_id (department_id);</span></span>
<span class="line"><span>#查看索引</span></span>
<span class="line"><span>SHOW INDEXES FROM employees;</span></span>
<span class="line"><span>#组合索引</span></span>
<span class="line"><span>CREATE INDEX idx_name_age ON employees(name, age);</span></span></code></pre></div><p>批量添加示例数据，这里是通过 gpt4.0，通过说生成 excel 类似格式的随机内容，然后生成一万条数据，再通过 navicat 工具进行导入操作。</p><p><strong>索引优化</strong></p><h4 id="最左前缀原则" tabindex="-1">最左前缀原则 <a class="header-anchor" href="#最左前缀原则" aria-label="Permalink to &quot;最左前缀原则&quot;">​</a></h4><p>最左前缀法则：带头大哥不能死，中间兄弟不能断</p><p>当面试的时候，建议不要从直接的表象去回答这些问题，建议结合一下相关的底层实现去讲；</p><p>比如说谈到啊最左前缀原则失效的时候，你可以讲一下，我们MySQL 的使用的存储引擎 innodb 中，采用 B+ 树的索引结构（这里可能会问一下为什么Mysql 会使用 B+ 树的数据结构，有一个 钩子点埋下）</p><p>然后这里可以围绕说，当我们沿着 B+ 树的叶子节点往下走的时候，如果说前缀未匹配（带头大哥不能死，中间兄弟不能断），这个树节点就走不下去（不走索引）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410190357.png" alt="image.png"></p><p>核心思想是围绕索引 ”有序“ 这个点出发去讲。</p><h4 id="索引类上少计算数" tabindex="-1">索引类上少计算数 <a class="header-anchor" href="#索引类上少计算数" aria-label="Permalink to &quot;索引类上少计算数&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>explain select * from employees where left(name,2) = &#39;He&#39;;</span></span></code></pre></div><p>这种情况下，会进行的是全表扫描操作，当他实际上在索引列上使用到了函数，他实际会对于当前索引数下，当前列每一个节点进行运算，从而会进行全表扫描。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410192702.png" alt="image.png"></p><p>优化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>explain select * from employees where name like &#39;He%&#39;;</span></span></code></pre></div><p>通过 like 运算，进行后缀查询操作，这种情况下会走索引（有序操作），从而这里会实际走了范围索引查询。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410193006.png" alt="image.png"></p><p>总结：不在索引类上做任何操作（计算、函数、（自动 or 手动）类型转换），会导致索引失效而转向全表扫描。</p><p>核心就围绕一个：有序，尽可能走叶子节点下有序的操作。</p><h4 id="范围后面全失效" tabindex="-1">范围后面全失效 <a class="header-anchor" href="#范围后面全失效" aria-label="Permalink to &quot;范围后面全失效&quot;">​</a></h4><h4 id="select-使用明确字段-尽可能使用覆盖索引" tabindex="-1">select 使用明确字段（尽可能使用覆盖索引） <a class="header-anchor" href="#select-使用明确字段-尽可能使用覆盖索引" aria-label="Permalink to &quot;select 使用明确字段（尽可能使用覆盖索引）&quot;">​</a></h4><h4 id="不等空值或者-or" tabindex="-1">不等空值或者 or <a class="header-anchor" href="#不等空值或者-or" aria-label="Permalink to &quot;不等空值或者 or&quot;">​</a></h4><p>如果出现 != 或者 or 的时候，可以考虑使用强制使用索引的操作；</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410194918.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>explain select name,age from employees where name != &#39;Colleen Perry&#39; or name = &#39;Marcus Wilson&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>explain select name,age from employees FORCE INDEX(idx_name_age_part) where name != &#39;Colleen Perry&#39; or name = &#39;Marcus Wilson&#39;</span></span></code></pre></div><p>当使用强制索引 idx_name_age_part，第二步他这里走的是范围查询索引，扫描的行数变少了一些（数据量大的话更明显）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410194935.png" alt="image.png"></p><h4 id="var-引号不能丢" tabindex="-1">VAR 引号不能丢 <a class="header-anchor" href="#var-引号不能丢" aria-label="Permalink to &quot;VAR 引号不能丢&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410195606.png" alt="image.png"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>explain select name,age from employees where name = 30;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>explain select name,age from employees where name = &#39;30&#39;;</span></span></code></pre></div><p>当 var 类型使用的查询条件这里使用数字的话，他隐含的操作是类型转换操作，会将字段内容转换为数值类型，再进行查询操作，因此这里会进行全表扫描操作；</p><p>因此建议 var 引号不能丢。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240410195634.png" alt="image.png"></p>`,39)])])}const g=e(i,[["render",l]]);export{m as __pageData,g as default};
